USE db_catalogo;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, generic_name VARCHAR(180), barcode VARCHAR(80) UNIQUE, category_id BIGINT UNSIGNED NULL, presentation VARCHAR(100) NOT NULL DEFAULT 'Unidad', price DECIMAL(12,2) NOT NULL DEFAULT 0, reorder_level INT UNSIGNED NOT NULL DEFAULT 10, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (category_id) REFERENCES categories(id)) ENGINE=InnoDB;
INSERT IGNORE INTO categories (id,name) VALUES (1,'Analgésicos'),(2,'Antibióticos'),(3,'Vitaminas'),(4,'Otros');
